import type { HTMLAttributes, TdHTMLAttributes, ThHTMLAttributes } from "react";
import { cx, flag } from "../utils/cx";

export type TableProps = HTMLAttributes<HTMLTableElement> & {
  /** Keep the header row in view while the table scrolls inside its container. */
  stickyHeader?: boolean;
  /** Accessible name of the scroll container (the table needs a `TableCaption` or `aria-label` too). */
  containerLabel?: string;
  containerClassName?: string;
};

/**
 * A hairline-row table. It sits in a horizontally scrollable, keyboard-focusable container so wide tables never break
 * the page layout. Server-compatible: sorting is just a prop on `TableHead`.
 */
export function Table({ stickyHeader, containerLabel, containerClassName, className, ...rest }: TableProps) {
  return (
    <div
      className={cx("hm-table-wrap", containerClassName)}
      role="region"
      aria-label={containerLabel ?? rest["aria-label"]}
      tabIndex={0}
      data-sticky={flag(stickyHeader)}
    >
      <table {...rest} className={cx("hm-table", className)} />
    </div>
  );
}

export function TableCaption({ className, ...rest }: HTMLAttributes<HTMLTableCaptionElement>) {
  return <caption {...rest} className={cx("hm-table-caption", className)} />;
}
export function TableHeader(props: HTMLAttributes<HTMLTableSectionElement>) {
  return <thead {...props} />;
}
export function TableBody(props: HTMLAttributes<HTMLTableSectionElement>) {
  return <tbody {...props} />;
}
export function TableRow({
  selected,
  className,
  ...rest
}: HTMLAttributes<HTMLTableRowElement> & { selected?: boolean }) {
  return (
    <tr
      {...rest}
      className={cx("hm-table-row", className)}
      data-selected={flag(selected)}
      aria-selected={selected || undefined}
    />
  );
}

export type TableHeadProps = Omit<ThHTMLAttributes<HTMLTableCellElement>, "align"> & {
  align?: "start" | "end";
  /** Makes the header a sort button. Pass the current direction; the handler should cycle it. */
  sort?: "ascending" | "descending" | "none";
  onSort?: () => void;
};

export function TableHead({ align = "start", sort, onSort, className, children, ...rest }: TableHeadProps) {
  return (
    <th
      scope="col"
      {...rest}
      className={cx("hm-table-head", className)}
      data-align={align}
      aria-sort={onSort ? (sort ?? "none") : undefined}
    >
      {onSort ? (
        <button type="button" className="hm-table-sort" onClick={onSort} data-sort={sort ?? "none"}>
          {children}
          <span className="hm-table-sort-icon" aria-hidden="true" />
        </button>
      ) : (
        children
      )}
    </th>
  );
}

export type TableCellProps = Omit<TdHTMLAttributes<HTMLTableCellElement>, "align"> & {
  align?: "start" | "end";
  /** Tabular figures, for amounts and counts. */
  numeric?: boolean;
  /** Render as a row header (`th scope="row"`), for the cell that names the row. */
  rowHeader?: boolean;
};

export function TableCell({ align, numeric, rowHeader, className, ...rest }: TableCellProps) {
  const props = {
    ...rest,
    className: cx("hm-table-cell", className),
    "data-align": align ?? (numeric ? "end" : "start"),
    "data-numeric": flag(numeric),
  };
  return rowHeader ? <th scope="row" {...(props as object)} /> : <td {...props} />;
}
